<script setup>
import {computed} from 'vue';import {store,estado,hoy,nombreCurso} from '../store';
const proximas=computed(()=>store.tareas.filter(t=>t.estado!=='Completado'&&t.fecha>=hoy()).sort((a,b)=>a.fecha.localeCompare(b.fecha)));
const indicadores=computed(()=>[['Cursos',store.cursos.length],['Pendientes',store.tareas.filter(t=>t.estado!=='Completado').length],['Completadas',store.tareas.filter(t=>t.estado==='Completado').length],['Vencidas',store.tareas.filter(t=>estado(t)==='Vencida').length]]);
</script><template><div class="d-flex justify-content-between align-items-center mb-3"><h2>Inicio</h2><RouterLink to="/actividades" class="btn btn-primary">Gestionar actividades</RouterLink></div><div class="p-4 bg-primary text-white rounded-3 mb-4"><h3>Organiza tu semestre</h3><p class="mb-0">Planifica tus entregas y mantén el control de tus estudios.</p></div><div class="row g-3 mb-4"><div v-for="i in indicadores" :key="i[0]" class="col-6 col-xl-3"><div class="card p-3"><small class="text-secondary">{{i[0]}}</small><h2>{{i[1]}}</h2></div></div></div><div class="card p-3"><h5>Próximas entregas</h5><p v-if="!proximas.length" class="text-secondary">No tienes entregas próximas.</p><div v-for="t in proximas.slice(0,5)" :key="t.id" class="border-bottom py-2"><strong>{{t.nombre}}</strong><div class="small text-secondary">{{nombreCurso(t.curso)}} · {{t.fecha}}</div></div></div></template>